{
  "rules": [
    {
      "category": "rent_increase_limit",
      "title": "Costa-Hawkins vacancy decontrol (prohibition on local initial rent controls)",
      "requirement": "Landlords have the right to set the initial rental rate at market rate upon a new tenancy, preempting local rent control ordinances from capping initial rents upon vacancy.",
      "requirement_es": "Los propietarios tienen el derecho de fijar libremente la tarifa inicial de alquiler con un nuevo inquilino al quedar desocupada la vivienda, impidiendo que las ordenanzas locales de control de alquileres limiten el alquiler inicial tras una desocupación.",
      "key_value": {
        "label": "initial rental rate restriction",
        "value": "no local cap (market rate upon vacancy)"
      },
      "coverage_conditions": {
        "type": "ALWAYS",
        "clauses": []
      },
      "exemptions": [
        {
          "description": "Previous tenancy terminated by the owner by notice pursuant to Section 1946.1 or terminated by change of terms pursuant to Section 827",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "__unknowable__"
              }
            ]
          }
        },
        {
          "description": "Owner agreed by contract with a public entity in consideration for a direct financial contribution or assistance under Gov Code 65915",
          "conditions": {
            "type": "OR",
            "clauses": [
              {
                "field": "rent_subsidized",
                "operator": "==",
                "value": true,
                "note": "contract with a public entity in consideration for direct financial contribution or assistance"
              }
            ]
          }
        },
        {
          "description": "Dwelling cited for serious health, safety, fire, or building code violations at least 60 days before vacancy that remained unabated",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "__unknowable__"
              }
            ]
          }
        }
      ],
      "effective_date": "2024-01-01",
      "superseded_date": null,
      "status": "enacted",
      "precedence": {
        "relationship": "supersedes",
        "target_scope": "local",
        "source_language": "Notwithstanding any other provision of law, an owner of residential real property may establish the initial rental rate for a dwelling or unit"
      },
      "penalty": null,
      "source_citation": "Cal. Civ. Code § 1954.53(a)",
      "quote": {
        "chunk": "c1",
        "start_words": "Notwithstanding any other provision of law,",
        "end_words": "a dwelling or unit, except where any of the following applies:"
      },
      "confidence": 0.95
    }
  ]
}
